mapper.update:
UPDATE `order`
SET status = #{status},

    pay_time = #{payTime},


    refund_time = #{refundTime}

WHERE id = #{id}

mapper.select:
SELECT o.id, o.order_no, o.user_id, u.username, o.total_price, o.status, o.create_time, o.pay_time FROM `order` o LEFT JOIN `user` u ON u.id = o.user_id
AND o.order_no LIKE CONCAT('%', #{orderNo}, '%')
AND o.user_id = #{userId}
AND o.status = #{status}
AND o.create_time >= #{startDate}
AND o.create_time < DATE_ADD(#{endDate}, INTERVAL 1 DAY)
ORDER BY o.create_time DESC
